<?php
require_once __DIR__ . '/bootstrap.php'; require_login();$page=max(1,(int)($_GET['page']??1));$limit=10;$pdo=get_db();$c=$pdo->prepare('SELECT COUNT(*) FROM orders WHERE user_id=?');$c->execute([current_user_id()]);$total=(int)$c->fetchColumn();$stmt=$pdo->prepare('SELECT reference,total,currency,payment_method,payment_status,order_status,created_at FROM orders WHERE user_id=? ORDER BY created_at DESC LIMIT '.$limit.' OFFSET '.(($page-1)*$limit));$stmt->execute([current_user_id()]);echo json_encode(['orders'=>$stmt->fetchAll(),'page'=>$page,'pages'=>max(1,(int)ceil($total/$limit)),'total'=>$total]);
